def merge_sorted(a, b):
    result = []
    i = 0
    j = 0
    n = len(a)
    m = len(b)
    while i < n and j < m:
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    while i < n:
        result.append(a[i])
        i += 1
    while j < m:
        result.append(b[j])
        j += 1
    return result

def chunked(values, size):
    if size <= 0:
        raise ValueError("size must be a positive integer")
    return [values[i:i + size] for i in range(0, len(values), size)]

