def trim_history(messages, budget):
    # Validate budget: must be a nonnegative integer (bool excluded).
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be a nonnegative integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate each message and its cost.
    for message in messages:
        if not isinstance(message, dict):
            raise ValueError("each message must be a dict")
        cost = message.get("cost")
        if isinstance(cost, bool) or not isinstance(cost, int):
            raise ValueError("each message cost must be an integer")
        if cost < 0:
            raise ValueError("each message cost must be nonnegative")

    # Find the longest contiguous suffix (ending at the last message)
    # whose summed cost fits the budget. Costs are nonnegative, so the
    # running sum grows monotonically as we extend toward the front.
    total = 0
    start = len(messages)
    for i in range(len(messages) - 1, -1, -1):
        if total + messages[i]["cost"] > budget:
            break
        total += messages[i]["cost"]
        start = i

    # Return a shallow copy of the suffix slice; do not mutate input.
    return messages[start:]

