def merge_tool_results(calls, results):
    # Map id -> result, last result for an id wins.
    result_map = {}
    for result in results:
        result_map[result['id']] = result

    seen = set()
    output = []
    for call in calls:
        cid = call['id']
        if cid in seen:
            raise ValueError(f'duplicate call id: {cid!r}')
        seen.add(cid)

        if cid in result_map:
            content = result_map[cid].get('content', '')
            output.append({'id': cid, 'status': 'done', 'content': content})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

