def summarize_usage(events):
    maxes = {}
    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)
        if input_count < 0 or output_count < 0:
            raise ValueError('token counts must be nonnegative')
        if request_id not in maxes:
            maxes[request_id] = {'input': input_count, 'output': output_count}
        else:
            maxes[request_id]['input'] = max(maxes[request_id]['input'], input_count)
            maxes[request_id]['output'] = max(maxes[request_id]['output'], output_count)
    total_input = sum(m['input'] for m in maxes.values())
    total_output = sum(m['output'] for m in maxes.values())
    return {'input': total_input, 'output': total_output}

