def trim_history(messages, budget):
    # Validate budget is a nonnegative integer.
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate every message is a dict with a nonnegative integer cost.
    for msg in messages:
        if not isinstance(msg, dict) or "cost" not in msg:
            raise ValueError("each message must be a dict with a 'cost'")
        cost = msg["cost"]
        if isinstance(cost, bool) or not isinstance(cost, int):
            raise ValueError("cost must be an integer")
        if cost < 0:
            raise ValueError("cost must be nonnegative")

    # Build the longest contiguous suffix (ending at the last message)
    # whose summed cost fits the budget. Suffixes are nested, so starting
    # from the newest message and accumulating backwards yields the
    # longest valid suffix. We never skip a newer message to keep an
    # older one: if the newest message alone exceeds the budget, the
    # result is empty. Zero-cost messages are naturally included.
    total = 0
    kept = []
    for msg in reversed(messages):
        cost = msg["cost"]
        if total + cost <= budget:
            total += cost
            kept.append(msg)
        else:
            break

    kept.reverse()
    return list(kept)

