def merge_tool_results(calls, results):
    # Reject duplicate call ids (do not mutate inputs).
    seen = set()
    for call in calls:
        cid = call['id']
        if cid in seen:
            raise ValueError("duplicate call id: %r" % (cid,))
        seen.add(cid)

    # Map id -> content. The last result for an id wins.
    # Results with unknown ids are ignored (never looked up below).
    content_by_id = {}
    for result in results:
        rid = result['id']
        content_by_id[rid] = result.get('content', '')

    # One entry per call, in call order.
    output = []
    for call in calls:
        cid = call['id']
        if cid in content_by_id:
            output.append({'id': cid, 'status': 'done', 'content': content_by_id[cid]})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

