def summarize_usage(events):
    max_input = {}
    max_output = {}

    for event in events:
        request_id = event['request_id']

        inp = event.get('input', 0)
        out = event.get('output', 0)

        if inp < 0:
            raise ValueError('input count must be nonnegative')
        if out < 0:
            raise ValueError('output count must be nonnegative')

        if request_id not in max_input or inp > max_input[request_id]:
            max_input[request_id] = inp
        if request_id not in max_output or out > max_output[request_id]:
            max_output[request_id] = out

    total_input = sum(max_input.values())
    total_output = sum(max_output.values())

    return {'input': total_input, 'output': total_output}

